public class Main {
    static String[] todos = new String[10];
    static int jumlah = 0;

    public static void main(String[] args) {
        tambah("Belajar Java");
        System.out.println("Pertama: " + todos[0]);
        System.out.println("Jumlah: " + jumlah);
        tambah("Cuci motor");
        tambah("Bayar listrik");
        System.out.println("Jumlah: " + jumlah);
        System.out.println("Terakhir: " + todos[jumlah - 1]);
        tambahDua("Masak", "Senam");
        System.out.println("Jumlah: " + jumlah);
        System.out.println("Terakhir sekarang: " + terakhir());
    }

    static void tambah(String isi) {
        todos[jumlah] = isi;
        jumlah++;
    }

    static void tambahDua(String a, String b) {
        tambah(a);
        tambah(b);
    }

    static String terakhir() {
        return todos[jumlah - 1];
    }
}

